<?php $productImage=$product['image_url']??(($isDemo??true)?asset('images/'.$product['image']):null); ?>
<article class="product-card" data-product data-id="<?= e($product['id']) ?>" data-category="<?= e($product['category_id']) ?>" data-name="<?= e($product['name']) ?>" data-sku="<?= e($product['sku']) ?>" data-unit="<?= e($product['unit']) ?>"><div class="product-image"><?php if($product['badge'])component('badge',['label'=>$product['badge']]);?><?php if($productImage):?><img src="<?= e($productImage) ?>" alt="<?= e($product['image_alt']??'') ?>" loading="lazy" width="280" height="220"><?php else:?><span class="product-image-empty" aria-label="Imagen no publicada">Imagen no publicada</span><?php endif?></div><div class="product-body"><p class="product-category"><?= e($product['category']) ?></p><h3><?= e($product['name']) ?></h3><p class="product-unit"><?= e($product['unit']) ?><?= ($isDemo??true)?' · Producto demo':'' ?></p><div class="product-bottom"><span><?= !($isDemo??true)&&($product['price']??null)!==null?'$'.e(number_format((float)$product['price'],2)).' MXN'.(($product['tax_included']??0)?' · impuesto incluido':''):'Precio por cotizar' ?></span><?php if($isDemo??true):?><button type="button" class="add-product" aria-label="Agregar <?= e($product['name']) ?> a la lista de demostración" disabled><?= icon('plus') ?></button><?php else:?><a class="add-product" href="<?= e($product['quote_href']) ?>" data-quote-open data-quote-variant="<?= e($product['id']) ?>" data-quote-description="<?= e($product['name']) ?>" data-quote-unit="<?= e($product['unit']) ?>" data-quote-sku="<?= e($product['sku']) ?>" aria-label="Solicitar cotización de <?= e($product['name']) ?>"><?= icon('arrow') ?></a><?php endif?></div></div></article>
